                # 可用性，但沿用时仍要写 e=now+ttl（下方处理）。
                keep = backend_routable(
                    backends.get(old_b), drain_strict=drain_strict
                )
            else:
                # 三键且 e 非 null：到期标志先于可用性判定。
                expired = now >= old_expires
                keep = not expired and backend_routable(
                    backends.get(old_b), drain_strict=drain_strict
                )
