            if now is not None and old_expires is None:
                # 三键沿用 e=null 项的可用 b：b 不变，但补写 e=now+ttl。
                new_expires = now + sticky_ttl
                sticky_map[key] = [old_b, new_expires]
                return old_b, True, False, False, new_expires
            # 其余沿用一律 e 不变。
